CREATE MATERIALIZED VIEW non_leaf_1484 AS
SELECT mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, t.id AS t_id, t.title AS t_title, t.imdb_index AS t_imdb_index, t.kind_id AS t_kind_id, t.production_year AS t_production_year, t.imdb_id AS t_imdb_id, t.phonetic_code AS t_phonetic_code, t.episode_of_id AS t_episode_of_id, t.season_nr AS t_season_nr, t.episode_nr AS t_episode_nr, t.series_years AS t_series_years, t.md5sum AS t_md5sum, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role
FROM movie_info AS mi1, title AS t, cast_info AS ci, role_type AS rt
WHERE ci.movie_id = t.id AND mi1.info_type_id = 4 AND mi1.info IN ('Arabic', 'Dutch', 'Finnish', 'Galician', 'Tagalog') AND t.id = mi1.movie_id AND ci.role_id = rt.id AND rt.role IN ('actor', 'actress', 'cinematographer', 'composer', 'costume designer');